import sys, csv, importlib.util, numpy as np, pymc as pm, collections
path=sys.argv[1]
spec=importlib.util.spec_from_file_location("m",path); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/2485af553ddb9dd3/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
if hasattr(m,'prepare_observed'):
    data=m.prepare_observed(rows)
else:
    fs=[m.compute_features(r['number_set'],r['target']) for r in rows]
    data={k:np.array([f[k] for f in fs]) for k in fs[0]}
    data['rating']=np.array([int(r['rating']) for r in rows])
with m.model:
    pm.set_data({k:(v.astype('int64') if k=='rating' else v) for k,v in data.items()})
    best=None
    for s in range(int(sys.argv[2]) if len(sys.argv)>2 else 3):
        mp=pm.find_MAP(progressbar=False,seed=s,maxeval=5000)
        lp=m.model.compile_logp()(mp)
        if best is None or lp>best[0]: best=(lp,mp)
    print("MAP logp",best[0])
    mp=best[1]
    for k,v in mp.items():
        if not k.endswith('__') and k!='p_yes': print(k,np.round(v,3))
    p=mp['p_yes']
d=collections.defaultdict(lambda:[[],[]])
for r,pp in zip(rows,p):
    ex=r['number_set'].split(',')
    if len(ex)==1 and r['target']!=ex[0]:
        d[ex[0]][0].append(int(r['rating'])); d[ex[0]][1].append(pp)
obs=[];pred=[]
for k,(a,b) in sorted(d.items(),key=lambda kv:np.mean(kv[1][0])):
    if len(a)>=20: obs.append(np.mean(a)); pred.append(np.mean(b))
    print(k,len(a),round(np.mean(a),2),round(np.mean(b),2))
print("sd obs",np.std(obs),"sd pred",np.std(pred))
